\begin{tikzpicture}
\begin{axis}[
    width=0.84\textwidth,
    height=0.46\textwidth,
    xmin=0, xmax=6.4,
    ymin=-5.1, ymax=5.1,
    axis lines=middle,
    xlabel={\(t\)},
    ylabel={\(y(t)\)},
    xtick={0,2.094,4.188,6.283},
    xticklabels={\(0\),\(\frac{2\pi}{3}\),\(\frac{4\pi}{3}\),\(2\pi\)},
    ytick={-4.472,0,4.472},
    yticklabels={\(-2\sqrt5\),\(0\),\(2\sqrt5\)},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=0:6.3, samples=400] {4*cos(deg(3*x))-2*sin(deg(3*x))};
\addplot[thick, dashed, domain=0:6.3, samples=2] {sqrt(20)};
\addplot[thick, dashed, domain=0:6.3, samples=2] {-sqrt(20)};
\node[anchor=south] at (rel axis cs:0.5,1.04) {\(y=4\cos(3t)-2\sin(3t)\)};
\node[anchor=north] at (rel axis cs:0.72,0.38) {amplitude \(2\sqrt5\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.62\textwidth, axis equal image,
    height=0.52\textwidth,
    xmin=-3.4, xmax=3.4,
    ymin=-6.6, ymax=6.6,
    axis lines=middle,
    xlabel={\(y\)},
    ylabel={\(y'\)},
    xtick={-3,0,3},
    ytick={-6,0,6},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=0:360, samples=300] ({3*cos(x)},{-6*sin(x)});
\draw[->, thick] (axis cs:3,0) -- (axis cs:2.954,-1.042) -- (axis cs:2.819,-2.052);
% Parameters and energy interpretation are in the caption.
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.84\textwidth,
    height=0.46\textwidth,
    xmin=0, xmax=18,
    ymin=-1.25, ymax=1.25,
    axis lines=middle,
    xlabel={\(t\)},
    ylabel={\(y(t)\)},
    xtick={0,5,10,15},
    ytick={-1,0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={draw=none, at={(0.98,0.97)}, anchor=north east}
]
\addplot[very thick, domain=0:18, samples=500] {exp(-0.18*x)*cos(deg(2*x))};
\addlegendentry{\(e^{-0.18t}\cos(2t)\)}
\addplot[thick, dashed, domain=0:18, samples=200] {exp(-0.18*x)};
\addlegendentry{envelope}
\addplot[thick, dashed, domain=0:18, samples=200] {-exp(-0.18*x)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.82\textwidth,
    height=0.46\textwidth,
    xmin=0, xmax=2.4,
    ymin=0, ymax=4.5,
    axis lines=left,
    xlabel={driving frequency \(\gamma\)},
    ylabel={steady-state amplitude},
    xtick={0,0.5,1,1.5,2},
    ytick={0,1,2,3,4},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=0:2.4, samples=400] {1/sqrt((1-x^2)^2+(0.25*x)^2)};
\draw[dashed] (axis cs:1,0) -- (axis cs:1,4.5);
\node[anchor=south] at (axis cs:1,4.5) {near natural frequency};
\node[anchor=west] at (axis cs:1.18,3.0) {large but finite response};
\node[anchor=west] at (axis cs:0.18,0.8) {\(m=k=F_0=1,\ c=0.25\)};
\end{axis}
\end{tikzpicture}
